package cue

import (
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
	cueerror "cuelang.org/go/cue/errors"
	"cuelang.org/go/encoding/yaml"
	yamlv3 "gopkg.in/yaml.v3"
)

const (
	jsonFormat = "json"
	textFormat = "text"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New("validation failed")
)

// ValidateBytes takes a slice of bytes, and validates them against a cue definition.
func ValidateBytes(b []byte) error {
	cctx := cuecontext.New()

	return validate(b, cctx)
}

func validate(b []byte, cctx *cue.Context) error {
	v := cctx.CompileBytes(cueFile)

	f, err := yaml.Extract("", b)
	if err != nil {
		return err
	}

	yv := cctx.BuildFile(f, cue.Scope(v))
	yv = v.Unify(yv)

	return yv.Validate()
}

// Location contains information about where an error has occurred during cue
// validation.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error is a collection of fields that represent positions in files where the user
// has made some kind of error.
type Error struct {
	Path     string   `json:"path"`
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

// Result contains every error found while validating a YAML document.
type Result struct {
	Errors []Error `json:"errors"`
}

// FeaturesValidator holds the compiled features schema.
type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if err := v.Err(); err != nil {
		return nil, err
	}
	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// Validate checks a YAML document and returns all of its validation errors.
func (validator *FeaturesValidator) Validate(file string, b []byte) (Result, error) {
	result := Result{Errors: []Error{}}
	f, err := yaml.Extract(file, b)
	if err == nil {
		value := validator.v.Unify(validator.cue.BuildFile(f, cue.Scope(validator.v)))
		err = value.Validate()
	}
	if err == nil {
		return result, nil
	}

	positions := yamlPositions(b, file)
	for _, issue := range cueerror.Errors(err) {
		path := strings.Join(issue.Path(), ".")
		message, args := issue.Msg()
		message = fmt.Sprintf(message, args...)
		if path != "" {
			message = path + ": " + message
		}
		location := Location{File: file}
		if entry, ok := positions[path]; ok {
			location = entry.value
			if strings.Contains(message, "field not allowed") {
				location = entry.key
			}
		} else {
			// Missing fields have no node of their own. Point to the closest
			// enclosing YAML value when one is available.
			for parent := path; parent != ""; {
				index := strings.LastIndex(parent, ".")
				if index < 0 {
					break
				}
				parent = parent[:index]
				if entry, ok := positions[parent]; ok {
					location = entry.value
					break
				}
			}
			for _, pos := range issue.InputPositions() {
				if location.Line == 0 && pos.IsValid() && pos.Filename() == file {
					location.Line, location.Column = pos.Line(), pos.Column()
					break
				}
			}
		}
		result.Errors = append(result.Errors, Error{Path: path, Message: message, Location: location})
	}
	if len(result.Errors) == 0 {
		result.Errors = append(result.Errors, Error{Message: err.Error(), Location: Location{File: file}})
	}
	return result, ErrValidationFailed
}

type fieldPositions struct {
	key   Location
	value Location
}

// yamlPositions uses the original YAML nodes because CUE's unified errors can
// point at a parent schema node when an unknown field is rejected.
func yamlPositions(b []byte, file string) map[string]fieldPositions {
	positions := make(map[string]fieldPositions)
	var root yamlv3.Node
	if err := yamlv3.Unmarshal(b, &root); err != nil {
		return positions
	}
	var walk func(*yamlv3.Node, string)
	walk = func(node *yamlv3.Node, path string) {
		switch node.Kind {
		case yamlv3.DocumentNode:
			for _, child := range node.Content {
				walk(child, path)
			}
		case yamlv3.MappingNode:
			for i := 0; i+1 < len(node.Content); i += 2 {
				key, value := node.Content[i], node.Content[i+1]
				childPath := key.Value
				if path != "" {
					childPath = path + "." + childPath
				}
				positions[childPath] = fieldPositions{
					key:   Location{File: file, Line: key.Line, Column: key.Column},
					value: Location{File: file, Line: value.Line, Column: value.Column},
				}
				walk(value, childPath)
			}
		case yamlv3.SequenceNode:
			for i, child := range node.Content {
				childPath := strconv.Itoa(i)
				if path != "" {
					childPath = path + "." + childPath
				}
				positions[childPath] = fieldPositions{key: Location{File: file, Line: child.Line, Column: child.Column}, value: Location{File: file, Line: child.Line, Column: child.Column}}
				walk(child, childPath)
			}
		}
	}
	walk(&root, "")
	return positions
}

func writeErrorDetails(format string, result Result, w io.Writer) error {
	var sb strings.Builder

	buildErrorMessage := func() {
		sb.WriteString("❌ Validation failure!\n\n")

		for i := 0; i < len(result.Errors); i++ {
			errString := fmt.Sprintf(`
- Message: %s
  Path   : %s
  File   : %s
  Line   : %d
  Column : %d
`, result.Errors[i].Message, result.Errors[i].Path, result.Errors[i].Location.File, result.Errors[i].Location.Line, result.Errors[i].Location.Column)

			sb.WriteString(errString)
		}
	}

	switch format {
	case jsonFormat:
		if err := json.NewEncoder(w).Encode(result); err != nil {
			return err
		}

		return nil
	case textFormat:
		buildErrorMessage()
	default:
		sb.WriteString("Invalid format chosen, defaulting to \"text\" format...\n")
		buildErrorMessage()
	}

	fmt.Fprint(w, sb.String())

	return nil
}

// ValidateFiles takes a slice of strings as filenames and validates them against
// our cue definition of features.
func ValidateFiles(dst io.Writer, files []string, format string) error {
	validator, err := NewFeaturesValidator()
	if err != nil {
		return err
	}
	result := Result{Errors: []Error{}}

	for _, f := range files {
		b, err := os.ReadFile(f)
		// Quit execution of the cue validating against the yaml
		// files upon failure to read file.
		if err != nil {
			return fmt.Errorf("read %s: %w", f, err)
		}
		fileResult, _ := validator.Validate(f, b)
		result.Errors = append(result.Errors, fileResult.Errors...)
	}

	if len(result.Errors) > 0 {
		if err := writeErrorDetails(format, result, dst); err != nil {
			return err
		}

		return ErrValidationFailed
	}

	// For json format upon success, return no output to the user
	if format == jsonFormat {
		return nil
	}

	if format != textFormat {
		fmt.Fprint(dst, "Invalid format chosen, defaulting to \"text\" format...\n")
	}

	fmt.Fprintln(dst, "✅ Validation success!")

	return nil
}

package main

import (
	"errors"
	"fmt"
	"os"

	"github.com/spf13/cobra"
	"go.flipt.io/flipt/internal/cue"
)

type validateCommand struct {
	issueExitCode int
	format        string
}

func newValidateCommand() *cobra.Command {
	v := &validateCommand{}

	cmd := &cobra.Command{
		Use:          "validate",
		Short:        "Validate a list of flipt features.yaml files",
		Run:          v.run,
		Hidden:       true,
		SilenceUsage: true,
	}

	cmd.Flags().IntVar(&v.issueExitCode, "issue-exit-code", 1, "Exit code to use when issues are found")

	cmd.Flags().StringVarP(
		&v.format,
		"format", "F",
		"text",
		"output format",
	)

	return cmd
}

func (v *validateCommand) run(cmd *cobra.Command, args []string) {
	if err := cue.ValidateFiles(cmd.OutOrStdout(), args, v.format); err != nil {
		if errors.Is(err, cue.ErrValidationFailed) {
			os.Exit(v.issueExitCode)
		}
		fmt.Fprintln(cmd.ErrOrStderr(), err)
		os.Exit(1)
	}
}

