229	// ValidateFiles takes a slice of strings as filenames and validates them against
230	// our cue definition of features.
231	func ValidateFiles(dst io.Writer, files []string, format string) error {
232		validator, err := NewFeaturesValidator()
233		if err != nil {
234			return err
235		}
236		result := Result{Errors: []Error{}}
237	
238		for _, f := range files {
239			b, err := os.ReadFile(f)
240			// Quit execution of the cue validating against the yaml
241			// files upon failure to read file.
242			if err != nil {
243				return fmt.Errorf("read %s: %w", f, err)
244			}
245			fileResult, _ := validator.Validate(f, b)
246			result.Errors = append(result.Errors, fileResult.Errors...)
247		}
248	
249		if len(result.Errors) > 0 {
250			if err := writeErrorDetails(format, result, dst); err != nil {
251				return err
252			}
253	
254			return ErrValidationFailed
255		}
256	
257		// For json format upon success, return no output to the user
258		if format == jsonFormat {
259			return nil
260		}
261	
262		if format != textFormat {
263			fmt.Fprint(dst, "Invalid format chosen, defaulting to \"text\" format...\n")
264		}
265	
266		fmt.Fprintln(dst, "✅ Validation success!")
267	
268		return nil
269	}
